  'rest.los_avisos_salen_por_whatsapp_al': 'Los avisos salen por WhatsApp al destinatario de abajo (sin destinatario no se manda nada) y los revisa el sistema cada ~15 minutos. El plazo y los días de aviso que captures aquí los usa el aviso; las pantallas de seguimiento siguen mostrando la regla de {plazoMesesDefault} meses que dijo el cliente mientras el proveedor no la confirme por escrito. El vencimiento de tus reclamos siempre se ve en la pantalla de seguimiento.',
