  'rest.las_casetas_que_cada_unidad_o': 'Las casetas que cada unidad, o cada convenio A→B, puede cruzar. Un pase en una caseta que <b>no</b> está en el curso aparece en el reporte de reclamación como «Cruce fuera de curso» (confianza media: el curso lo declara la flota). Sin curso declarado no se reclama nada por este motivo. Carga tu CSV o Excel<e1> codigo; nombre; unidad; convenio; casetas</e1> (una fila por curso; las casetas, en orden de recorrido y separadas por «|»; deben existir en el catálogo de casetas; la unidad es su número económico y el convenio, su nombre). Volver a cargar el mismo código lo actualiza. El corredor (<e2>corredor_wkt</e2> + <e3>buffer_m</e3>) se acepta, pero el formato real de tus rutas está pendiente: hoy se prueba con datos sintéticos.',
